168.         private static PositionRecord FindPosition(TradeRecord trade, IEnumerable<PositionRecord> candidates, ISet<string> usedPositions, ICollection<string> reasons)
169.         {
170.             var available = candidates.Where(candidate => !usedPositions.Contains(candidate.PositionId)).ToList();
171.             if (!available.Any())
172.             {
173.                 reasons.Add("MissingPosition");
174.                 return null;
175.             }
176. 
177.             var sameDate = available.Where(candidate => candidate.SettlementDate == trade.SettlementDate).ToList();
178.             if (!sameDate.Any())
179.             {
180.                 reasons.Add("PositionSettlementDateMismatch");
181.                 return null;
182.             }
183. 
184.             var sameCurrency = sameDate.Where(candidate => Normalize(candidate.Currency) == Normalize(trade.Currency)).ToList();
185.             if (!sameCurrency.Any())
186.             {
187.                 reasons.Add("PositionCurrencyMismatch");
188.                 return null;
189.             }
190. 
191.             var candidatePosition = sameCurrency
192.                 .OrderBy(candidate => Math.Abs(candidate.Quantity - trade.Quantity))
193.                 .ThenBy(candidate => candidate.PositionId, StringComparer.Ordinal)
194.                 .First();
195. 
196.             if (Math.Sign((double)candidatePosition.Quantity) != Math.Sign((double)trade.Quantity))
197.             {
198.                 reasons.Add("PositionQuantitySignMismatch");
199.                 return null;
200.             }
201. 
202.             if (Math.Abs(candidatePosition.Quantity - trade.Quantity) > BatchConfiguration.PositionQuantityTolerance)
203.             {
204.                 reasons.Add("PositionQuantityOutOfTolerance");
205.                 return null;
206.             }
207. 
208.             return candidatePosition;
209.         }
210. 
211.         private static SettlementRecord FindSettlement(TradeRecord trade, IEnumerable<SettlementRecord> candidates, ISet<string> usedSettlements, ICollection<string> reasons)
212.         {
213.             var available = candidates.Where(candidate => !usedSettlements.Contains(candidate.SettlementId)).ToList();
214.             if (!available.Any())
215.             {
216.                 reasons.Add("MissingSettlement");
217.                 return null;
218.             }
219. 
220.             var sameDate = available.Where(candidate => candidate.SettlementDate == trade.SettlementDate).ToList();
221.             if (!sameDate.Any())
222.             {
223.                 reasons.Add("SettlementDateMismatch");
224.                 return null;
225.             }
226. 
227.             var sameCurrency = sameDate.Where(candidate => Normalize(candidate.Currency) == Normalize(trade.Currency)).ToList();
228.             if (!sameCurrency.Any())
229.             {
230.                 reasons.Add("SettlementCurrencyMismatch");
231.                 return null;
232.             }
233. 
234.             var candidateSettlement = sameCurrency
235.                 .OrderBy(candidate => Math.Abs(candidate.Quantity - trade.Quantity))
236.                 .ThenBy(candidate => candidate.SettlementId, StringComparer.Ordinal)
237.                 .First();
238. 
239.             if (Math.Sign((double)candidateSettlement.Quantity) != Math.Sign((double)trade.Quantity))
240.             {
241.                 reasons.Add("SettlementQuantitySignMismatch");
242.                 return null;
243.             }
244. 
245.             if (Math.Abs(candidateSettlement.Quantity - trade.Quantity) > BatchConfiguration.SettlementQuantityTolerance)
246.             {
247.                 reasons.Add("SettlementQuantityOutOfTolerance");
248.                 return null;
249.             }
250. 
251.             if (Math.Abs(candidateSettlement.CashAmount - trade.NetAmount) > BatchConfiguration.SettlementAmountTolerance)
252.             {
253.                 reasons.Add("SettlementAmountOutOfTolerance");
254.                 return null;
255.             }
256. 
257.             return candidateSettlement;
258.         }
259. 
260.         private static string GetNearestPositionId(TradeRecord trade, IEnumerable<PositionRecord> candidates)
261.         {
262.             if (candidates == null)
263.             {
264.                 return null;
265.             }
266. 
267.             return candidates
268.                 .OrderBy(candidate => Math.Abs((candidate.SettlementDate - trade.SettlementDate).Ticks))
269.                 .ThenBy(candidate => candidate.PositionId, StringComparer.Ordinal)
270.                 .Select(candidate => candidate.PositionId)
271.                 .FirstOrDefault();
272.         }
273. 
274.         private static string GetNearestSettlementId(TradeRecord trade, IEnumerable<SettlementRecord> candidates)
275.         {
276.             if (candidates == null)
277.             {
278.                 return null;
279.             }
280. 
281.             return candidates
282.                 .OrderBy(candidate => Math.Abs((candidate.SettlementDate - trade.SettlementDate).Ticks))
283.                 .ThenBy(candidate => candidate.SettlementId, StringComparer.Ordinal)
284.                 .Select(candidate => candidate.SettlementId)
285.                 .FirstOrDefault();
286.         }
287. 
288.         private static BreakRecord CreateBreak(TradeRecord trade, string reasons, string positionId, string settlementId, bool canManualOverride)
289.         {
290.             return new BreakRecord
291.             {
292.                 TradeId = Normalize(trade.TradeId),
293.                 Account = Normalize(trade.Account),
294.                 Instrument = Normalize(trade.Instrument),
295.                 Quantity = trade.Quantity,
296.                 SettlementDate = trade.SettlementDate,
297.                 Currency = Normalize(trade.Currency),
298.                 Reasons = reasons,
299.                 PositionId = positionId,
300.                 SettlementId = settlementId,
301.                 CanManualOverride = canManualOverride
302.             };
303.         }
304. 
305.         private static MatchedTradeRecord CreateMatchedTrade(TradeRecord trade, string status, string positionId, string settlementId, string note)
306.         {
307.             return new MatchedTradeRecord
308.             {
309.                 TradeId = Normalize(trade.TradeId),
310.                 Status = status,
311.                 Account = Normalize(trade.Account),
312.                 Instrument = Normalize(trade.Instrument),
313.                 Quantity = trade.Quantity,
314.                 SettlementDate = trade.SettlementDate,
315.                 Currency = Normalize(trade.Currency),
316.                 PositionId = positionId,
317.                 SettlementId = settlementId,
318.                 OverrideNote = note
319.             };
320.         }
321. 
322.         private static string BuildPairKey(string account, string instrument)
323.         {
324.             return Normalize(account) + "|" + Normalize(instrument);
325.         }
326. 
327.         private static string Normalize(string value)
328.         {
329.             return (value ?? string.Empty).Trim().ToUpperInvariant();
330.         }
331.     }
332. }
