namespace LegacyTradeReconciliation.Domain;

/// <summary>A trade as delivered by the front office feed.</summary>
public sealed record TradeRecord(
    string TradeId,
    string Account,
    string Instrument,
    decimal Quantity,
    DateOnly SettlementDate,
    string Currency,
    decimal NetAmount);

/// <summary>A custodian position that a trade can be reconciled against.</summary>
public sealed record PositionRecord(
    string PositionId,
    string Account,
    string Instrument,
    decimal Quantity,
    DateOnly SettlementDate,
    string Currency);

/// <summary>A settlement instruction that a trade can be reconciled against.</summary>
public sealed record SettlementRecord(
    string SettlementId,
    string Account,
    string Instrument,
    decimal Quantity,
    DateOnly SettlementDate,
    string Currency,
    decimal CashAmount);

/// <summary>
/// An operator instruction that may resolve a break.
/// <para>
/// Reference identity is deliberately significant: the audit rules distinguish
/// between two textually identical instructions delivered on separate rows, so
/// callers must never deduplicate overrides by value.
/// </para>
/// </summary>
public sealed record ManualOverrideRecord(
    string TradeId,
    string Action,
    string Note,
    string ApprovedBy);

namespace LegacyTradeReconciliation.Domain;

/// <summary>A row of <c>matched-trades.csv</c>.</summary>
public sealed record MatchedTradeRecord(
    string TradeId,
    string Status,
    string Account,
    string Instrument,
    decimal Quantity,
    DateOnly SettlementDate,
    string Currency,
    string? PositionId,
    string? SettlementId,
    string? OverrideNote);

/// <summary>A row of <c>break-queue.csv</c> plus the internal override eligibility flag.</summary>
public sealed record BreakRecord(
    string TradeId,
    string Account,
    string Instrument,
    decimal Quantity,
    DateOnly SettlementDate,
