using LegacyTradeReconciliation.Abstractions;
using LegacyTradeReconciliation.Configuration;
using LegacyTradeReconciliation.Domain;

namespace LegacyTradeReconciliation.Application;

/// <summary>
/// Reconciles trades against positions and settlements and applies manual overrides.
/// </summary>
/// <remarks>
/// <para>
/// This is the behavioural core of the batch and its rules are load bearing for Trade
/// Operations. The modernization deliberately preserves every externally observable
/// decision, including reason-code spelling, candidate selection order, override
/// eligibility, and the exact composition and ordering of the stale-override audit
/// trail.
/// </para>
/// <para>
/// The engine is pure: it performs no I/O, takes its thresholds from
/// <see cref="ReconciliationOptions"/>, and returns a fully ordered result. That makes
/// the business rules directly unit testable without touching the file system.
/// </para>
/// </remarks>
