    {
        ArgumentNullException.ThrowIfNull(options);
        options.Validate();
        _options = options;
    }

    public ReconciliationResult Reconcile(
        IReadOnlyCollection<TradeRecord> trades,
        IReadOnlyCollection<PositionRecord> positions,
        IReadOnlyCollection<SettlementRecord> settlements,
        IReadOnlyCollection<ManualOverrideRecord> overrides)
    {
        ArgumentNullException.ThrowIfNull(trades);
        ArgumentNullException.ThrowIfNull(positions);
        ArgumentNullException.ThrowIfNull(settlements);
        ArgumentNullException.ThrowIfNull(overrides);

        var matchedTrades = new List<MatchedTradeRecord>();
        var breakQueue = new List<BreakRecord>();
        var staleOverrides = new StaleOverrideLog();

        // The first instruction for a trade wins. Later instructions are never silently
        // dropped; they are surfaced as stale so the audit trail stays complete.
        var overrideGroups = overrides
            .GroupBy(record => Normalize(record.TradeId), StringComparer.Ordinal)
            .ToList();
        var overrideMap = overrideGroups.ToDictionary(
            group => group.Key,
            group => group.First(),
            StringComparer.Ordinal);
        foreach (ManualOverrideRecord superseded in overrideGroups.SelectMany(group => group.Skip(1)))
        {
            staleOverrides.Add(superseded);
        }

        var positionsByPair = positions
            .GroupBy(position => BuildPairKey(position.Account, position.Instrument), StringComparer.Ordinal)
            .ToDictionary(
                group => group.Key,
                group => (IReadOnlyList<PositionRecord>)[.. group.OrderBy(position => position.PositionId, StringComparer.Ordinal)],
                StringComparer.Ordinal);

        var settlementsByPair = settlements
            .GroupBy(settlement => BuildPairKey(settlement.Account, settlement.Instrument), StringComparer.Ordinal)
            .ToDictionary(
                group => group.Key,
                group => (IReadOnlyList<SettlementRecord>)[.. group.OrderBy(settlement => settlement.SettlementId, StringComparer.Ordinal)],
                StringComparer.Ordinal);

        var usedPositions = new HashSet<string>(StringComparer.Ordinal);
        var usedSettlements = new HashSet<string>(StringComparer.Ordinal);
        var seenTradeIds = new HashSet<string>(StringComparer.Ordinal);
        int duplicateTradeCount = 0;

        foreach (TradeRecord trade in trades)
        {
            string normalizedTradeId = Normalize(trade.TradeId);
            if (!seenTradeIds.Add(normalizedTradeId))
            {
                duplicateTradeCount++;
                breakQueue.Add(CreateBreak(trade, BreakReasons.DuplicateTradeId, null, null, canManualOverride: false));
                continue;
            }

            if (trade.Quantity <= 0m || trade.NetAmount <= 0m)
            {
                breakQueue.Add(CreateBreak(trade, BreakReasons.TradeValueOutOfBounds, null, null, canManualOverride: false));
                continue;
            }

            string pairKey = BuildPairKey(trade.Account, trade.Instrument);
            var reasons = new List<string>();

            positionsByPair.TryGetValue(pairKey, out IReadOnlyList<PositionRecord>? positionCandidates);
            PositionRecord? position = positionCandidates is null
                ? AddReason(reasons, BreakReasons.MissingPosition, default(PositionRecord))
                : FindPosition(trade, positionCandidates, usedPositions, reasons);

            settlementsByPair.TryGetValue(pairKey, out IReadOnlyList<SettlementRecord>? settlementCandidates);
            SettlementRecord? settlement = settlementCandidates is null
                ? AddReason(reasons, BreakReasons.MissingSettlement, default(SettlementRecord))
                : FindSettlement(trade, settlementCandidates, usedSettlements, reasons);

            if (reasons.Count == 0 && position is not null && settlement is not null)
            {
                usedPositions.Add(position.PositionId);
                usedSettlements.Add(settlement.SettlementId);
