        var resolvedTrades = new HashSet<string>(StringComparer.Ordinal);
        foreach (BreakRecord breakRecord in breakQueue.ToList())
        {
            if (!overrideMap.TryGetValue(breakRecord.TradeId, out ManualOverrideRecord? manualOverride))
            {
                continue;
            }

            // The instruction targeted a real break, so it is no longer "unmatched"
            // even if it turns out to be unusable.
