        }

        var sameDate = available.Where(candidate => candidate.SettlementDate == trade.SettlementDate).ToList();
        if (sameDate.Count == 0)
        {
            return AddReason(reasons, BreakReasons.PositionSettlementDateMismatch, default(PositionRecord));
        }

        var sameCurrency = sameDate.Where(candidate => CurrencyMatches(candidate.Currency, trade.Currency)).ToList();
        if (sameCurrency.Count == 0)
        {
            return AddReason(reasons, BreakReasons.PositionCurrencyMismatch, default(PositionRecord));
        }

        PositionRecord candidatePosition = sameCurrency
            .OrderBy(candidate => Math.Abs(candidate.Quantity - trade.Quantity))
            .ThenBy(candidate => candidate.PositionId, StringComparer.Ordinal)
            .First();

        if (Math.Sign(candidatePosition.Quantity) != Math.Sign(trade.Quantity))
        {
            return AddReason(reasons, BreakReasons.PositionQuantitySignMismatch, default(PositionRecord));
        }

        if (Math.Abs(candidatePosition.Quantity - trade.Quantity) > _options.PositionQuantityTolerance)
