            breakQueue.Remove(breakRecord);
        }

        foreach (ManualOverrideRecord record in overrides)
        {
            if (!resolvedTrades.Contains(Normalize(record.TradeId)))
            {
                staleOverrides.Add(record);
            }
        }

        IReadOnlyList<ManualOverrideRecord> orderedStaleOverrides =
            [.. staleOverrides.OrderBy(record => record.TradeId, StringComparer.Ordinal)];

        return new ReconciliationResult(
            MatchedTrades: [.. matchedTrades.OrderBy(record => record.TradeId, StringComparer.Ordinal)],
            OpenBreaks: [.. breakQueue.OrderBy(record => record.TradeId, StringComparer.Ordinal)],
            StaleOverrides: orderedStaleOverrides,
            TotalTradesRead: trades.Count,
            CanonicalTradeCount: seenTradeIds.Count,
            DuplicateTradeCount: duplicateTradeCount,
            MatchedCount: matchedTrades.Count(record => record.Status == MatchStatuses.Matched),
            ManualOverrideMatchedCount: matchedTrades.Count(record => record.Status == MatchStatuses.ManualOverrideMatched),
            ManualOverrideSuppressedCount: matchedTrades.Count(record => record.Status == MatchStatuses.ManualOverrideSuppressed));
    }

    private PositionRecord? FindPosition(
        TradeRecord trade,
        IReadOnlyList<PositionRecord> candidates,
        HashSet<string> usedPositions,
        List<string> reasons)
    {
        var available = candidates.Where(candidate => !usedPositions.Contains(candidate.PositionId)).ToList();
        if (available.Count == 0)
        {
            return AddReason(reasons, BreakReasons.MissingPosition, default(PositionRecord));
        }

        var sameDate = available.Where(candidate => candidate.SettlementDate == trade.SettlementDate).ToList();
        if (sameDate.Count == 0)
        {
            return AddReason(reasons, BreakReasons.PositionSettlementDateMismatch, default(PositionRecord));
        }

        var sameCurrency = sameDate.Where(candidate => CurrencyMatches(candidate.Currency, trade.Currency)).ToList();
        if (sameCurrency.Count == 0)
        {
            return AddReason(reasons, BreakReasons.PositionCurrencyMismatch, default(PositionRecord));
        }

        PositionRecord candidatePosition = sameCurrency
            .OrderBy(candidate => Math.Abs(candidate.Quantity - trade.Quantity))
            .ThenBy(candidate => candidate.PositionId, StringComparer.Ordinal)
            .First();

        if (Math.Sign(candidatePosition.Quantity) != Math.Sign(trade.Quantity))
        {
            return AddReason(reasons, BreakReasons.PositionQuantitySignMismatch, default(PositionRecord));
        }

        if (Math.Abs(candidatePosition.Quantity - trade.Quantity) > _options.PositionQuantityTolerance)
        {
            return AddReason(reasons, BreakReasons.PositionQuantityOutOfTolerance, default(PositionRecord));
        }

        return candidatePosition;
    }

    private SettlementRecord? FindSettlement(
        TradeRecord trade,
        IReadOnlyList<SettlementRecord> candidates,
        HashSet<string> usedSettlements,
        List<string> reasons)
    {
        var available = candidates.Where(candidate => !usedSettlements.Contains(candidate.SettlementId)).ToList();
        if (available.Count == 0)
        {
            return AddReason(reasons, BreakReasons.MissingSettlement, default(SettlementRecord));
        }

        var sameDate = available.Where(candidate => candidate.SettlementDate == trade.SettlementDate).ToList();
        if (sameDate.Count == 0)
        {
            return AddReason(reasons, BreakReasons.SettlementDateMismatch, default(SettlementRecord));
        }

        var sameCurrency = sameDate.Where(candidate => CurrencyMatches(candidate.Currency, trade.Currency)).ToList();
        if (sameCurrency.Count == 0)
        {
            return AddReason(reasons, BreakReasons.SettlementCurrencyMismatch, default(SettlementRecord));
        }

        SettlementRecord candidateSettlement = sameCurrency
            .OrderBy(candidate => Math.Abs(candidate.Quantity - trade.Quantity))
            .ThenBy(candidate => candidate.SettlementId, StringComparer.Ordinal)
            .First();

        if (Math.Sign(candidateSettlement.Quantity) != Math.Sign(trade.Quantity))
        {
            return AddReason(reasons, BreakReasons.SettlementQuantitySignMismatch, default(SettlementRecord));
        }

        if (Math.Abs(candidateSettlement.Quantity - trade.Quantity) > _options.SettlementQuantityTolerance)
        {
            return AddReason(reasons, BreakReasons.SettlementQuantityOutOfTolerance, default(SettlementRecord));
        }

        if (Math.Abs(candidateSettlement.CashAmount - trade.NetAmount) > _options.SettlementAmountTolerance)
        {
            return AddReason(reasons, BreakReasons.SettlementAmountOutOfTolerance, default(SettlementRecord));
        }

        return candidateSettlement;
    }

    /// <summary>
    /// Best-effort hint for the operator working the break queue. It intentionally
    /// ignores currency, tolerance and prior consumption: it only answers "which
    /// counterpart is closest in settlement date?".
    /// </summary>
    private static string? GetNearestPositionId(TradeRecord trade, IReadOnlyList<PositionRecord>? candidates) =>
        candidates?
            .OrderBy(candidate => Math.Abs(candidate.SettlementDate.DayNumber - trade.SettlementDate.DayNumber))
            .ThenBy(candidate => candidate.PositionId, StringComparer.Ordinal)
            .Select(candidate => candidate.PositionId)
            .FirstOrDefault();

    private static string? GetNearestSettlementId(TradeRecord trade, IReadOnlyList<SettlementRecord>? candidates) =>
        candidates?
            .OrderBy(candidate => Math.Abs(candidate.SettlementDate.DayNumber - trade.SettlementDate.DayNumber))
            .ThenBy(candidate => candidate.SettlementId, StringComparer.Ordinal)
            .Select(candidate => candidate.SettlementId)
            .FirstOrDefault();

    private static string FormatReasons(IEnumerable<string> reasons) =>
        string.Join("|", reasons.Distinct(StringComparer.Ordinal).OrderBy(reason => reason, StringComparer.Ordinal));

    private static T? AddReason<T>(List<string> reasons, string reason, T? result)
        where T : class
    {
        reasons.Add(reason);
        return result;
    }

    private static BreakRecord CreateBreak(
        TradeRecord trade,
        string reasons,
        string? positionId,
        string? settlementId,
        bool canManualOverride) =>
        new(
            Normalize(trade.TradeId),
            Normalize(trade.Account),
            Normalize(trade.Instrument),
            trade.Quantity,
            trade.SettlementDate,
            Normalize(trade.Currency),
            reasons,
            positionId,
            settlementId,
            canManualOverride);

    private static MatchedTradeRecord CreateMatchedTrade(
        TradeRecord trade,
        string status,
        string? positionId,
        string? settlementId,
        string? note) =>
        new(
            Normalize(trade.TradeId),
            status,
            Normalize(trade.Account),
            Normalize(trade.Instrument),
            trade.Quantity,
            trade.SettlementDate,
            Normalize(trade.Currency),
            positionId,
            settlementId,
            note);

    private static bool CurrencyMatches(string left, string right) =>
        string.Equals(Normalize(left), Normalize(right), StringComparison.Ordinal);

    private static string BuildPairKey(string account, string instrument) =>
        Normalize(account) + "|" + Normalize(instrument);

    /// <summary>
    /// Account, instrument, currency and trade identifiers are compared on trimmed,
    /// upper-cased values so that feed-side casing and padding never create a break.
    /// </summary>
    private static string Normalize(string? value) =>
        (value ?? string.Empty).Trim().ToUpperInvariant();

    /// <summary>
    /// Ordered audit trail of unusable override instructions.
    /// <para>
    /// Membership is tracked by <em>reference</em>, not by value. Two separate rows that
    /// happen to carry identical text are distinct instructions and must both be
    /// reported; collapsing them would hide an operator's duplicate submission.
    /// </para>
    /// </summary>
    private sealed class StaleOverrideLog : IEnumerable<ManualOverrideRecord>
    {
        private readonly List<ManualOverrideRecord> _ordered = [];
        private readonly HashSet<ManualOverrideRecord> _seen = new(ReferenceEqualityComparer.Instance);

        public void Add(ManualOverrideRecord record)
        {
            if (_seen.Add(record))
            {
                _ordered.Add(record);
            }
        }

        public IEnumerator<ManualOverrideRecord> GetEnumerator() => _ordered.GetEnumerator();

        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();
    }
}

