2. 
3. namespace LegacyTradeReconciliation.Configuration;
4. 
5. /// <summary>A validated request to run the batch for one business date.</summary>
6. public sealed record RunRequest(DateOnly BusinessDate, string InputDirectory, string OutputDirectory);
7. 
8. /// <summary>The outcome of interpreting the process command line.</summary>
9. public sealed record CommandLineParseResult(RunRequest? Request, string? ErrorMessage, bool HelpRequested)
10. {
11.     public static CommandLineParseResult Success(RunRequest request) => new(request, null, false);
12. 
13.     public static CommandLineParseResult Failure(string message) => new(null, message, false);
14. 
15.     public static CommandLineParseResult Help() => new(null, null, true);
16. }
17. 
18. /// <summary>
19. /// Parses the batch command line.
20. /// <para>
21. /// The historical contract is preserved exactly: no arguments runs the bundled
22. /// sample, and three arguments supply business date, input directory and output
23. /// directory. Unlike the legacy build, an operator mistake now yields a readable
24. /// diagnostic and a non-zero exit code instead of an unhandled exception and a
25. /// stack trace on the console.
26. /// </para>
27. /// </summary>
28. public static class CommandLineParser
29. {
30.     public const string DateFormat = "yyyy-MM-dd";
31. 
32.     public static string Usage =>
33.         "Usage: LegacyTradeReconciliation [<business-date yyyy-MM-dd> <input-directory> <output-directory>]" +
34.         Environment.NewLine +
35.         "  With no arguments the bundled sample batch under data/sample is processed." +
36.         Environment.NewLine +
37.         "  Options: --help | -h    Show this message.";
38. 
39.     public static CommandLineParseResult Parse(string[]? args, string baseDirectory)
40.     {
41.         ArgumentException.ThrowIfNullOrEmpty(baseDirectory);
42. 
43.         args ??= [];
44. 
45.         if (args.Length == 1 && (args[0] is "--help" or "-h" or "/?"))
46.         {
47.             return CommandLineParseResult.Help();
48.         }
49. 
50.         if (args.Length == 0)
51.         {
52.             return CommandLineParseResult.Success(new RunRequest(
53.                 new DateOnly(2025, 3, 17),
54.                 Path.Combine(baseDirectory, "data", "sample"),
55.                 Path.Combine(baseDirectory, "output", "sample")));
56.         }
57. 
58.         if (args.Length != 3)
59.         {
60.             return CommandLineParseResult.Failure(
61.                 $"Expected either no arguments or 3 arguments but received {args.Length}.");
62.         }
63. 
64.         if (!DateOnly.TryParseExact(args[0], DateFormat, CultureInfo.InvariantCulture, DateTimeStyles.None, out DateOnly businessDate))
65.         {
66.             return CommandLineParseResult.Failure($"Business date '{args[0]}' is not a valid {DateFormat} date.");
67.         }
68. 
69.         if (!TryResolveDirectory(args[1], "Input directory", out string inputDirectory, out string? inputError))
70.         {
71.             return CommandLineParseResult.Failure(inputError);
72.         }
73. 
74.         if (!TryResolveDirectory(args[2], "Output directory", out string outputDirectory, out string? outputError))
75.         {
76.             return CommandLineParseResult.Failure(outputError);
77.         }
78. 
79.         return CommandLineParseResult.Success(new RunRequest(businessDate, inputDirectory, outputDirectory));
80.     }
81. 
82.     /// <summary>
83.     /// Resolves a caller-supplied path to a rooted, canonical form. Rooting the path
84.     /// up front means every later file operation is unaffected by the process working
85.     /// directory, and malformed paths are rejected before any file is touched.
86.     /// </summary>
87.     private static bool TryResolveDirectory(string value, string label, out string resolved, out string error)
88.     {
89.         resolved = string.Empty;
90.         error = string.Empty;
91. 
92.         if (string.IsNullOrWhiteSpace(value))
93.         {
94.             error = $"{label} must not be empty.";
95.             return false;
96.         }
97. 
98.         try
99.         {
100.             resolved = Path.GetFullPath(value);
101.             return true;
102.         }
103.         catch (Exception exception) when (exception is ArgumentException or NotSupportedException or PathTooLongException)
104.         {
105.             error = $"{label} '{value}' is not a usable path: {exception.Message}";
106.             return false;
107.         }
108.     }
109. }
110.

