using LegacyTradeReconciliation.Configuration;
using LegacyTradeReconciliation.Domain;
using Xunit;

namespace Reconciliation.Tests;

/// <summary>Rule-level tests for the reconciliation engine.</summary>
public sealed class MatchingEngineTests
{
    [Fact]
    public void A_clean_trade_matches_its_position_and_settlement()
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade()],
            [Build.Position()],
            [Build.Settlement()]);

        MatchedTradeRecord matched = Assert.Single(result.MatchedTrades);
        Assert.Equal(MatchStatuses.Matched, matched.Status);
        Assert.Equal("P-1", matched.PositionId);
        Assert.Equal("S-1", matched.SettlementId);
        Assert.Empty(result.OpenBreaks);
        Assert.Equal(1, result.CanonicalTradeCount);
        Assert.Equal(0, result.DuplicateTradeCount);
    }

    [Fact]
    public void Identifiers_are_compared_case_insensitively_and_trimmed()
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(tradeId: " t-1 ", account: " acc-1 ", instrument: "aaa.n", currency: "usd")],
            [Build.Position(account: "ACC-1", instrument: "AAA.N", currency: "USD")],
            [Build.Settlement(account: "ACC-1", instrument: "AAA.N", currency: "USD")]);

        MatchedTradeRecord matched = Assert.Single(result.MatchedTrades);
        Assert.Equal(MatchStatuses.Matched, matched.Status);
        Assert.Equal("T-1", matched.TradeId);
    }

    [Fact]
    public void A_repeated_trade_id_keeps_the_first_row_and_breaks_the_rest()
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(), Build.Trade()],
            [Build.Position()],
            [Build.Settlement()]);

        Assert.Single(result.MatchedTrades);
        BreakRecord duplicate = Assert.Single(result.OpenBreaks);
        Assert.Equal(BreakReasons.DuplicateTradeId, duplicate.Reasons);
        Assert.False(duplicate.CanManualOverride);
        Assert.Equal(2, result.TotalTradesRead);
        Assert.Equal(1, result.DuplicateTradeCount);
    }

    [Theory]
    [InlineData(0, 1000)]
    [InlineData(-5, 1000)]
    [InlineData(100, 0)]
    [InlineData(100, -1)]
    public void A_non_positive_quantity_or_amount_is_rejected_before_matching(decimal quantity, decimal netAmount)
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(quantity: quantity, netAmount: netAmount)],
            [Build.Position(quantity: quantity)],
            [Build.Settlement(quantity: quantity, cashAmount: netAmount)]);

        BreakRecord broken = Assert.Single(result.OpenBreaks);
        Assert.Equal(BreakReasons.TradeValueOutOfBounds, broken.Reasons);
        Assert.False(broken.CanManualOverride);
    }

    [Fact]
    public void A_trade_without_a_position_breaks_and_cannot_be_overridden()
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade()],
            [],
            [Build.Settlement()],
            [Build.Override()]);

        BreakRecord broken = Assert.Single(result.OpenBreaks);
        Assert.Equal(BreakReasons.MissingPosition, broken.Reasons);
        Assert.False(broken.CanManualOverride);
        Assert.Null(broken.PositionId);
        Assert.Single(result.StaleOverrides);
    }

    [Fact]
    public void Each_counterpart_is_consumed_by_at_most_one_trade()
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(tradeId: "T-1"), Build.Trade(tradeId: "T-2")],
            [Build.Position()],
            [Build.Settlement()]);

        Assert.Single(result.MatchedTrades);
        BreakRecord broken = Assert.Single(result.OpenBreaks);
        Assert.Equal("T-2", broken.TradeId);
        Assert.Equal("MissingPosition|MissingSettlement", broken.Reasons);
    }

    [Fact]
    public void The_closest_quantity_wins_when_several_counterparts_are_available()
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(quantity: 100m)],
            [Build.Position(positionId: "P-9", quantity: 500m), Build.Position(positionId: "P-2", quantity: 100m)],
            [Build.Settlement()]);

        MatchedTradeRecord matched = Assert.Single(result.MatchedTrades);
        Assert.Equal("P-2", matched.PositionId);
    }

    [Theory]
    [InlineData(0.01, true)]
    [InlineData(0.011, false)]
    public void The_position_quantity_tolerance_is_inclusive(decimal difference, bool shouldMatch)
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(quantity: 100m)],
            [Build.Position(quantity: 100m + difference)],
            [Build.Settlement(quantity: 100m + difference)]);

        if (shouldMatch)
        {
            Assert.Empty(result.OpenBreaks);
            return;
        }

        BreakRecord broken = Assert.Single(result.OpenBreaks);
        Assert.Contains(BreakReasons.PositionQuantityOutOfTolerance, broken.Reasons, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(0.02, true)]
    [InlineData(0.03, false)]
    public void The_settlement_quantity_tolerance_is_wider_than_the_position_tolerance(decimal difference, bool shouldMatch)
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(quantity: 100m)],
            [Build.Position(quantity: 100m)],
            [Build.Settlement(quantity: 100m + difference)]);

        if (shouldMatch)
        {
            Assert.Empty(result.OpenBreaks);
            return;
        }

        Assert.Equal(BreakReasons.SettlementQuantityOutOfTolerance, Assert.Single(result.OpenBreaks).Reasons);
    }

    [Theory]
    [InlineData(5.00, true)]
    [InlineData(5.01, false)]
    public void The_settlement_cash_tolerance_is_inclusive(decimal difference, bool shouldMatch)
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(netAmount: 1000m)],
            [Build.Position()],
            [Build.Settlement(cashAmount: 1000m + difference)]);

        if (shouldMatch)
        {
            Assert.Empty(result.OpenBreaks);
            return;
        }

        Assert.Equal(BreakReasons.SettlementAmountOutOfTolerance, Assert.Single(result.OpenBreaks).Reasons);
    }

    [Fact]
    public void Tolerances_are_configurable()
    {
        var strict = new ReconciliationOptions { PositionQuantityTolerance = 0m };

        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(quantity: 100m)],
            [Build.Position(quantity: 100.01m)],
            [Build.Settlement(quantity: 100.01m)],
            options: strict);

        Assert.Equal(BreakReasons.PositionQuantityOutOfTolerance, Assert.Single(result.OpenBreaks).Reasons);
    }

    [Fact]
    public void A_negative_tolerance_is_rejected()
    {
        var options = new ReconciliationOptions { SettlementAmountTolerance = -1m };

        Assert.Throws<ArgumentOutOfRangeException>(options.Validate);
    }

    [Fact]
    public void An_opposite_sign_counterpart_never_matches_however_close_it_is()
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(quantity: 100m)],
            [Build.Position(quantity: -100m)],
            [Build.Settlement(quantity: -100m)]);

        BreakRecord broken = Assert.Single(result.OpenBreaks);
        Assert.Equal(
            "PositionQuantitySignMismatch|SettlementQuantitySignMismatch",
            broken.Reasons);
    }

    [Fact]
    public void Reasons_are_deduplicated_and_sorted_for_stable_reporting()
    {
        var otherDate = new DateOnly(2025, 3, 20);

        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(currency: "USD")],
            [Build.Position(currency: "EUR", settlementDate: otherDate)],
            [Build.Settlement(currency: "EUR", settlementDate: otherDate)]);

        BreakRecord broken = Assert.Single(result.OpenBreaks);
        string[] reasons = broken.Reasons.Split('|');

        Assert.Equal(reasons.OrderBy(reason => reason, StringComparer.Ordinal), reasons);
        Assert.Equal(reasons.Distinct(), reasons);
        Assert.Contains(BreakReasons.PositionCurrencyMismatch, reasons);
        Assert.Contains(BreakReasons.PositionSettlementDateMismatch, reasons);
    }

    [Fact]
    public void A_break_reports_the_nearest_counterpart_ids_for_investigation()
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(currency: "USD")],
            [Build.Position(positionId: "P-7", currency: "EUR")],
            [Build.Settlement(settlementId: "S-7", currency: "EUR")]);

        BreakRecord broken = Assert.Single(result.OpenBreaks);
        Assert.Equal("P-7", broken.PositionId);
        Assert.Equal("S-7", broken.SettlementId);
        Assert.True(broken.CanManualOverride);
    }

    [Fact]
    public void Force_match_turns_an_eligible_break_into_an_audited_match()
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(currency: "USD")],
            [Build.Position(currency: "EUR")],
            [Build.Settlement(currency: "EUR")],
            [Build.Override(action: "forcematch", note: "Ops approved FX rebook")]);

        Assert.Empty(result.OpenBreaks);
        MatchedTradeRecord matched = Assert.Single(result.MatchedTrades);
        Assert.Equal(MatchStatuses.ManualOverrideMatched, matched.Status);
        Assert.Equal("Ops approved FX rebook", matched.OverrideNote);
        Assert.Equal(1, result.ManualOverrideMatchedCount);
        Assert.Empty(result.StaleOverrides);
    }

    [Fact]
    public void Suppress_break_records_the_suppression_instead_of_a_match()
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(currency: "USD")],
            [Build.Position(currency: "EUR")],
            [Build.Settlement(currency: "EUR")],
            [Build.Override(action: "SuppressBreak", note: "Known feed defect")]);

        Assert.Empty(result.OpenBreaks);
        MatchedTradeRecord matched = Assert.Single(result.MatchedTrades);
        Assert.Equal(MatchStatuses.ManualOverrideSuppressed, matched.Status);
        Assert.Equal(1, result.ManualOverrideSuppressedCount);
        Assert.Equal(0, result.MatchedCount);
    }

    [Theory]
    [InlineData("", "ops-manager")]
    [InlineData("   ", "ops-manager")]
    [InlineData("Approved", "")]
    [InlineData("Approved", "   ")]
    public void An_unapproved_or_unexplained_override_is_refused_and_audited(string note, string approvedBy)
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(currency: "USD")],
            [Build.Position(currency: "EUR")],
            [Build.Settlement(currency: "EUR")],
            [Build.Override(note: note, approvedBy: approvedBy)]);

        Assert.Single(result.OpenBreaks);
        Assert.Single(result.StaleOverrides);
        Assert.Empty(result.MatchedTrades);
    }

    [Fact]
    public void An_unrecognised_override_verb_is_refused_and_audited()
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(currency: "USD")],
            [Build.Position(currency: "EUR")],
            [Build.Settlement(currency: "EUR")],
            [Build.Override(action: "DeleteEverything")]);

        Assert.Single(result.OpenBreaks);
        Assert.Equal("DeleteEverything", Assert.Single(result.StaleOverrides).Action);
    }

    [Fact]
    public void Only_the_first_instruction_for_a_trade_is_applied()
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(currency: "USD")],
            [Build.Position(currency: "EUR")],
            [Build.Settlement(currency: "EUR")],
            [
                Build.Override(note: "First instruction"),
                Build.Override(note: "Superseded instruction"),
            ]);

        MatchedTradeRecord matched = Assert.Single(result.MatchedTrades);
        Assert.Equal("First instruction", matched.OverrideNote);
        Assert.Equal("Superseded instruction", Assert.Single(result.StaleOverrides).Note);
    }

    [Fact]
    public void An_override_for_an_unknown_trade_is_audited()
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade()],
            [Build.Position()],
            [Build.Settlement()],
            [Build.Override(tradeId: "T-DOES-NOT-EXIST")]);

        Assert.Equal("T-DOES-NOT-EXIST", Assert.Single(result.StaleOverrides).TradeId);
    }

    [Fact]
    public void Results_are_ordered_by_trade_id_so_output_is_reproducible()
    {
        ReconciliationResult result = Build.Reconcile(
            [Build.Trade(tradeId: "T-3"), Build.Trade(tradeId: "T-1"), Build.Trade(tradeId: "T-2")],
            [Build.Position(positionId: "P-1"), Build.Position(positionId: "P-2"), Build.Position(positionId: "P-3")],
            [Build.Settlement(settlementId: "S-1"), Build.Settlement(settlementId: "S-2"), Build.Settlement(settlementId: "S-3")]);

        Assert.Equal(["T-1", "T-2", "T-3"], result.MatchedTrades.Select(trade => trade.TradeId));
    }
}

