using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;

// Minimal xunit-compatible reflection runner. The sealed benchmark environment has no
// .NET SDK, so `dotnet test` cannot be used; this executes [Fact]/[Theory] methods directly.
internal static class Runner
{
    private static int Main(string[] args)
    {
        var assembly = Assembly.LoadFrom(args[0]);
        int passed = 0;
        var failures = new List<string>();

        foreach (Type type in assembly.GetTypes().Where(t => t.IsClass && t.IsPublic).OrderBy(t => t.Name, StringComparer.Ordinal))
        {
            foreach (MethodInfo method in type.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly).OrderBy(m => m.Name, StringComparer.Ordinal))
            {
                var attributes = method.GetCustomAttributes(false);
                bool isFact = attributes.Any(a => a.GetType().Name == "FactAttribute");
                bool isTheory = attributes.Any(a => a.GetType().Name == "TheoryAttribute");
                if (!isFact && !isTheory)
                {
                    continue;
                }

                var cases = new List<object?[]>();
                if (isTheory)
                {
                    foreach (object attribute in attributes.Where(a => a.GetType().Name == "InlineDataAttribute"))
                    {
                        var data = (IEnumerable<object?[]>)attribute.GetType()
                            .GetMethod("GetData")!
                            .Invoke(attribute, new object?[] { method })!;
                        cases.AddRange(data);
                    }
                }
                else
                {
                    cases.Add(Array.Empty<object?>());
                }

                foreach (object?[] arguments in cases)
                {
                    string label = type.Name + "." + method.Name +
                        (arguments.Length == 0 ? string.Empty : "(" + string.Join(", ", arguments.Select(Describe)) + ")");
                    try
                    {
                        object? instance = method.IsStatic ? null : Activator.CreateInstance(type);
                        method.Invoke(instance, Coerce(method, arguments));
                        passed++;
                    }
                    catch (TargetInvocationException exception)
                    {
                        failures.Add(label + Environment.NewLine + "    " + exception.InnerException);
                    }
                    catch (Exception exception)
                    {
                        failures.Add(label + Environment.NewLine + "    " + exception);
                    }
                }
            }
        }

        Console.WriteLine("passed: " + passed + ", failed: " + failures.Count);
        foreach (string failure in failures)
        {
            Console.WriteLine("FAIL " + failure);
        }

        return failures.Count == 0 ? 0 : 1;
    }

    private static object?[] Coerce(MethodInfo method, object?[] arguments)
    {
        ParameterInfo[] parameters = method.GetParameters();
        var coerced = new object?[arguments.Length];
        for (int i = 0; i < arguments.Length; i++)
        {
            object? value = arguments[i];
            Type target = parameters[i].ParameterType;
            coerced[i] = value is null || target.IsInstanceOfType(value)
                ? value
                : Convert.ChangeType(value, target, System.Globalization.CultureInfo.InvariantCulture);
        }

        return coerced;
    }

    private static string Describe(object? value) => value switch
    {
        null => "null",
        string text => "\"" + text + "\"",
        IEnumerable sequence and not string => "[" + string.Join(", ", sequence.Cast<object?>().Select(Describe)) + "]",
        _ => value.ToString() ?? string.Empty,
    };
}

